begin;
do $$
declare c uuid:=gen_random_uuid();c2 uuid:=gen_random_uuid();s uuid:=gen_random_uuid();s2 uuid:=gen_random_uuid();t uuid;n integer;
 p text:='HRT-Fixture-'||gen_random_uuid();x jsonb;y jsonb;rev integer;
 fragen jsonb; a jsonb;k jsonb:='{"name":"Max Testperson","verein":"Testverein","einstufung":"Kreisliga"}';
begin
 insert into public.vereine(id,name) values(c,'HRT-Rollback'),(c2,'HRT-Rollback-Fremd');
 select coalesce(min(id),0)-1 into n from public.obmann_zugang;
 insert into public.obmann_zugang(id,passwort,verein_id) values(n,p,c),(n-1,p||'-fremd',c2);
 insert into public.schiedsrichter(id,name,verein_id,pin,aktiv,ist_test) values(s,'HRT eigene Testperson',c,'938527',true,true),(s2,'HRT fremde Testperson',c2,'938528',true,true);
 select jsonb_agg('Fragetext Nummer '||i),jsonb_agg('Meine erste Antwort '||i) into fragen,a from generate_series(1,10) i;
 x:=public.obmann_hausregeltest_bereitstellen(p,'Test',fragen,now()+interval '1 day',now()+interval '1 day',now()+interval '2 days');
 t:=(x#>>'{test,id}')::uuid;
 y:=public.obmann_hausregeltest_bereitstellen(p,'Nicht überschreiben',fragen,now()+interval '2 days',now()+interval '2 days',now()+interval '3 days');
 if y#>>'{test,titel}'<>'Test' then raise exception 'TEST Test überschrieben';end if;
 set local role anon;
 x:=public.hausregeltest_laden(s,'938527');if x->>'phase'<>'vorbereitung' then raise exception 'TEST Phase';end if;
 begin perform public.hausregeltest_laden(s,'falsch');raise exception 'TEST PIN umgangen';exception when raise_exception then if sqlerrm like 'TEST%' then raise;end if;end;
 begin perform public.obmann_hausregeltest_laden('falsch');raise exception 'TEST Passwort umgangen';exception when raise_exception then if sqlerrm like 'TEST%' then raise;end if;end;
 if public.hausregeltest_laden(s2,'938528') is not null then raise exception 'TEST Fremdverein';end if;
 begin perform public.hausregeltest_speichern(s2,'938528',t,0,'vorbereitung',a,k,false);raise exception 'TEST Fremdschreiben';exception when raise_exception then if sqlerrm like 'TEST%' then raise;end if;end;
 x:=public.hausregeltest_speichern(s,'938527',t,0,'vorbereitung',a,k,false);
 if x->>'revision'<>'1' or x->'antworten'<>a then raise exception 'TEST Speichern';end if;
 begin perform public.hausregeltest_speichern(s,'938527',t,0,'vorbereitung',a,k,false);raise exception 'TEST Veraltete Revision';exception when raise_exception then if sqlerrm like 'TEST%' then raise;end if;end;
 begin perform public.hausregeltest_speichern(s,'938527',t,1,'endfassung',a,k,true);raise exception 'TEST Frühe Endfassung';exception when raise_exception then if sqlerrm like 'TEST%' then raise;end if;end;
 reset role;
 update private.hausregeltests set vorbereitung_bis=now()-interval '1 day',endfassung_ab=now()-interval '1 hour' where id=t;
 set local role anon;
 x:=public.hausregeltest_laden(s,'938527');if x->>'phase'<>'endfassung' or x->'antworten'<>a then raise exception 'TEST Übernahme';end if;
 begin perform public.hausregeltest_speichern(s,'938527',t,1,'vorbereitung',a,k,false);raise exception 'TEST Vorantwort nach Frist';exception when raise_exception then if sqlerrm like 'TEST%' then raise;end if;end;
 begin perform public.hausregeltest_speichern(s,'938527',t,1,'endfassung',jsonb_set(a,'{0}','""'),k,true);raise exception 'TEST Leere Endantwort';exception when raise_exception then if sqlerrm like 'TEST%' then raise;end if;end;
 x:=public.hausregeltest_speichern(s,'938527',t,1,'endfassung',jsonb_set(a,'{0}','"Überarbeitete eigene Antwort"'),k,true);
 if x#>>'{vor_antworten,0}'<>'Meine erste Antwort 1' or x#>>'{bestaetigt,antworten,0}'<>'Überarbeitete eigene Antwort' then raise exception 'TEST Erstfassung verloren';end if;
 y:=public.obmann_hausregeltest_laden(p);if y#>>'{personen,0,bestaetigt,kopf,name}'<>'Max Testperson' then raise exception 'TEST Obmann Export';end if;
 x:=public.hausregeltest_speichern(s,'938527',t,2,'endfassung',a,k,false);
 if x->'bestaetigt'<>'null'::jsonb then raise exception 'TEST Alte Bestätigung';end if;
 reset role;
 if (select count(*) from private.hausregeltest_fassungen where test_id=t)<>1 then raise exception 'TEST Historie';end if;
 update private.hausregeltests set abgabe_bis=now()-interval '1 second' where id=t;
 set local role anon;
 begin perform public.hausregeltest_speichern(s,'938527',t,3,'endfassung',a,k,true);raise exception 'TEST Abgabefrist umgangen';exception when raise_exception then if sqlerrm like 'TEST%' then raise;end if;end;
 reset role;
 if has_table_privilege('anon','private.hausregeltest_antworten','SELECT') or has_table_privilege('authenticated','private.hausregeltest_fassungen','SELECT') or has_function_privilege('anon','private.hrt_pruefen(jsonb,jsonb,integer,boolean)','EXECUTE') then raise exception 'TEST Direktrechte';end if;
 raise notice 'PASS HRT: Rollen, Phasen, Konflikt, Endfassung, Historie, Fristen';
end $$;
rollback;
select 'Hausregeltest-Rollback bestanden' as ergebnis;
